head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDBNF25300";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — bndMktactTpCd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_datefmt_cal_procsReqDd();
        scwin.init_datefmt_cal_rsnOccrDd();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf25300.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb1", fn: function () { return String(dma_result.get("listAmt")) + " 원"; } },
        { childId: "__rb2", fn: function () { return String(dma_result.get("bfchgExerPrc")) + " 원"; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_datefmt_cal_procsReqDd
 * @description 초기화 — datefmt cal procs Req Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_procsReqDd = function () { $c.date.checkCalendarFormat("cal_procsReqDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_datefmt_cal_rsnOccrDd
 * @description 초기화 — datefmt cal rsn Occr Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_rsnOccrDd = function () { $c.date.checkCalendarFormat("cal_rsnOccrDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.getBdchrgInfo($c.util.getComponent('slc_bdchrgTpCd'));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf25300.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_mpd_files_select_onclick
 * @description 「파일선택」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_mpd_files_select_onclick = function () {
    try { $c.util.onUploadClick($c.util.getComponent('mpd_files'));
    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf25300.btn_mpd_files_select_onclick' }); }
};

/**
 * @method
 * @name btn_mpd_files_del_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_mpd_files_del_onclick = async function () {
    try { const d = $c.util.getComponent('dlt_files'); const g = $c.util.getComponent('grd_mpd_files'); const u = $c.util.getComponent('mpd_files'); if (!d || !g) { return; } const idx = g.getCheckedIndex ? g.getCheckedIndex('CHK') : []; if (!idx || !idx.length) { return; } for (let i = idx.length - 1; i >= 0; i--) { try { const nm = d.getCellData(idx[i], 'FILE_NM'); if (u && u.removeFile) { u.removeFile(nm); } } catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: 'mpd_files.del' }); } } if (d.removeRows) { d.removeRows(idx); }
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf25300.btn_mpd_files_del_onclick' }); }
};

/**
 * @method
 * @name ipt_stkRelCorpbndExerPrc_onkeyup
 * @description ipt_stkRelCorpbndExerPrc 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_stkRelCorpbndExerPrc_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        $c.util.getComponent('txt_stkRelCorpbndExerPrcHanview').setValue($c.num.formatNumberKor(String((((selfVar) && (selfVar).getValue) ? (selfVar).getValue() : ((((selfVar) && typeof (selfVar).val === 'function') ? (selfVar).val() : (((selfVar) && (selfVar).value !== undefined) ? (selfVar).value : (selfVar))))) == null ? '' : (((selfVar) && (selfVar).getValue) ? (selfVar).getValue() : ((((selfVar) && typeof (selfVar).val === 'function') ? (selfVar).val() : (((selfVar) && (selfVar).value !== undefined) ? (selfVar).value : (selfVar)))))).replace(/,/g, '')));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf25300.ipt_stkRelCorpbndExerPrc_onkeyup' }); }
};

/**
 * @method
 * @name ipt_stkRelCorpbndExerPrc_onpaste
 * @description ipt_stkRelCorpbndExerPrc onpaste 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_stkRelCorpbndExerPrc_onpaste = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf25300.ipt_stkRelCorpbndExerPrc_onpaste' }); }
};

/**
 * @method
 * @name slc_chgRsnContn1_onchange
 * @description slc_chgRsnContn1 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_chgRsnContn1_onchange = function(e){
    try {
        scwin.onchangeChgRsnContn1();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf25300.slc_chgRsnContn1_onchange' }); }
};

/**
 * @method
 * @name ipt_chgRsnContn2_onpaste
 * @description ipt_chgRsnContn2 onpaste 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_chgRsnContn2_onpaste = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf25300.ipt_chgRsnContn2_onpaste' }); }
};

/**
 * @method
 * @name slc_bdchrgTpCd_onchange
 * @description slc_bdchrgTpCd 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_bdchrgTpCd_onchange = async function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.getBdchrgInfo(selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf25300.slc_bdchrgTpCd_onchange' }); }
};

/**
 * @method
 * @name btn_fileBrowse_onclick
 * @description btn_fileBrowse 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_fileBrowse_onclick = function(e){
    try {
        $c.util.onUploadClick($c.util.getComponent('mpd_files'))

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf25300.btn_fileBrowse_onclick' }); }
};

/**
 * @method
 * @name btn_delRow_onclick
 * @description btn_delRow 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_delRow_onclick = function(e){
    try {
        fn_delRow()  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_delRow — 폼·DOM 의존(B-7)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf25300.btn_delRow_onclick' }); }
};

/**
 * @method
 * @name btn_CheckValues_onclick
 * @description btn_CheckValues 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_CheckValues_onclick = function(e){
    try {
        CheckValues('__self.form',(String(((dma_pageContext.get("bndMktactTpCd") ?? "")) == null ? '' : ((dma_pageContext.get("bndMktactTpCd") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("bndMktactTpCd") ?? "")) == null ? '' : ((dma_pageContext.get("bndMktactTpCd") ?? "")))))

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf25300.btn_CheckValues_onclick' }); }
};

/**
 * @method
 * @name btn_goToList_onclick
 * @description btn_goToList 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_goToList_onclick = function(e){
    try {
        goToList()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf25300.btn_goToList_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_GetBdchrgInfo
 * @description Get Bdchrg Info 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_GetBdchrgInfo = async function () {
    const sbmOptions = {
        id: "tx_fn_GetBdchrgInfo",
        method: "post",
        action: "/account/userInfo.do?method=selectBdchrgDtlInfo",
        ref: "dma_GetBdchrgInfoReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/account/userInfo.do?method=selectBdchrgDtlInfo",
        ref: "dma_loadListReq",
        target: "dlt_bdchrgTpCdList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name mpd_files_selectCallback
 * @description mpd files select Callback 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name onchangeChgRsnContn1
 * @description onchange Chg Rsn Contn1 처리
 * @returns {void}
 * @hidden N
 */
scwin.onchangeChgRsnContn1 = function () {
    const stat = $c.util.getComponent('slc_chgRsnContn1').getValue();
    if (stat === "기타") {
        $c.util.getComponent('ipt_chgRsnContn2').setDisabled(false);
        $c.util.getComponent("ipt_chgRsnContn2").focus();
    } else {
        $c.util.getComponent('ipt_chgRsnContn2').setDisabled(true);
    }
};

/**
 * @method
 * @name setTelNo
 * @description set Tel No 처리
 * @param {*} pTelNo pTelNo
 * @returns {void}
 * @hidden N
 */
scwin.setTelNo = function (pTelNo) {
    if (pTelNo != null && pTelNo !== '') {
        const pTelNoArr = pTelNo.split('-');
        if (pTelNoArr.length === 3) {
            if (pTelNoArr[0] === "00") {
                $c.util.getComponent('ipt_apctTelNo1').setValue("");
            } else {
                $c.util.getComponent('ipt_apctTelNo1').setValue(pTelNoArr[0]);
            }
            $c.util.getComponent('ipt_apctTelNo2').setValue(pTelNoArr[1]);
            $c.util.getComponent('ipt_apctTelNo3').setValue(pTelNoArr[2]);
        } else {

        }
    }
};

/**
 * @method
 * @name setCellphoneNo
 * @description set Cellphone No 처리
 * @param {*} pCellphoneNo pCellphoneNo
 * @returns {void}
 * @hidden N
 */
scwin.setCellphoneNo = function (pCellphoneNo) {
    if (pCellphoneNo != null && pCellphoneNo !== '') {
        const pCellphoneNoArr = pCellphoneNo.split('-');
        if (pCellphoneNoArr.length === 3) {
            $c.util.getComponent('ipt_encrypCellphoneNo1').setValue(pCellphoneNoArr[0]);
            $c.util.getComponent('ipt_encrypCellphoneNo2').setValue(pCellphoneNoArr[1]);
            $c.util.getComponent('ipt_encrypCellphoneNo3').setValue(pCellphoneNoArr[2]);
        } else {

        }
    }
};

/**
 * @method
 * @name setEmail
 * @description set Email 처리
 * @param {*} pEmail pEmail
 * @returns {void}
 * @hidden N
 */
scwin.setEmail = function (pEmail) {
    if (pEmail != null && pEmail !== '') {
        const pEmailArr = pEmail.split('@');
        if (pEmailArr.length === 2) {
            $c.util.getComponent('ipt_encrypApctEmail1').setValue(pEmailArr[0]);
            $c.util.getComponent('ipt_encrypApctEmail2').setValue(pEmailArr[1]);
        } else {

        }
    }
};

/**
 * @method
 * @name setFaxNo
 * @description set Fax No 처리
 * @param {*} pFaxNo pFaxNo
 * @returns {void}
 * @hidden N
 */
scwin.setFaxNo = function (pFaxNo) {
    if (pFaxNo != null && pFaxNo !== '') {
        const pFaxNoArr = pFaxNo.split('-');
        if (pFaxNoArr.length === 3) {
            if (pFaxNoArr[0] === "00") {
                $c.util.getComponent('ipt_apctFaxNo1').setValue("");
            } else {
                $c.util.getComponent('ipt_apctFaxNo1').setValue(pFaxNoArr[0]);
            }
            $c.util.getComponent('ipt_apctFaxNo2').setValue(pFaxNoArr[1]);
            $c.util.getComponent('ipt_apctFaxNo3').setValue(pFaxNoArr[2]);
        } else {

        }
    }
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name getBdchrgInfoDone
 * @description get Bdchrg Info Done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.getBdchrgInfoDone = function (data) {
    const result = (typeof data === "string" ? JSON.parse(data) : data);
    $c.util.getComponent('ipt_chrgId').setValue(result.chrg_id);
    $c.util.getComponent('ipt_apctNm').setValue(result.chrg_nm);
    $c.util.getComponent('ipt_jobposNm').setValue(result.jobpos_nm);
    $c.util.getComponent('ipt_belngInstNm').setValue(result.belng_inst_nm);
    $c.util.getComponent('ipt_belngDepNm').setValue(result.belng_dep_nm);
    scwin.setTelNo(result.tel_no);
    scwin.setCellphoneNo(result.cellphone_no);
    scwin.setEmail(result.email);
    scwin.setFaxNo(result.fax_no);
};

/**
 * @method
 * @name getBdchrgInfo
 * @description get Bdchrg Info 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getBdchrgInfo = async function () {
    const r = await scwin.tx_fn_GetBdchrgInfo();
    try {
        scwin.getBdchrgInfoDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldbnf25300.fn_GetBdchrgInfo' });
    }
    return r;
};
